import unittest
from weekly_key import *
from datetime import date

class WeeklyKey(unittest.TestCase):
    def test_iso_week_year_boundaries(self):
        rows=[('2005-01-01',(2004,53)),('2006-01-01',(2005,52)),('2006-01-02',(2006,1)),('2012-12-31',(2013,1)),('2021-01-01',(2020,53)),('2024-12-30',(2025,1)),('2024-06-05',(2024,23))]
        for raw,expected in rows:
            with self.subTest(raw=raw):
                self.assertEqual(week_key(date.fromisoformat(raw)),expected)

if __name__ == '__main__':
    unittest.main()

